import type { Question } from '../../lib/types'
export const secrets_cloudtrail_questions: Question[] = [
  { id: 'd1-sec-001', domain: 1, topics: ['Secrets Manager', 'rotation'], type: 'single', stem: 'An RDS password is stored in Secrets Manager. The rotation Lambda fails. What happens to the secret?', options: [{ id: 'A', text: 'The secret is automatically rolled back to the previous version on failure' }, { id: 'B', text: 'AWSCURRENT stays on the last good version; the secret remains usable while rotation is retried' }, { id: 'C', text: 'Secrets Manager marks the secret as expired and blocks all access until rotation succeeds' }, { id: 'D', text: 'The secret is deleted after three consecutive failed rotation attempts' }], correct: ['B'], explanation: 'Secrets Manager keeps AWSCURRENT pointing to the last known good version. Failed rotation leaves the current secret intact — applications continue to work; rotation is retried on schedule.', distractors: { A: 'No rollback is needed because AWSCURRENT was never replaced — the existing version remains active throughout a failed rotation.', C: 'Secrets Manager never blocks access on rotation failure — the current version remains fully accessible.', D: 'Secrets are not deleted on rotation failure — the rotation schedule retries automatically.' } },
  { id: 'd1-sec-002', domain: 1, topics: ['Secrets Manager', 'rotation'], type: 'single', stem: 'Secrets Manager rotation is configured for every 30 days. When does the first rotation happen?', options: [{ id: 'A', text: 'Exactly 30 days after the secret is created per the schedule' }, { id: 'B', text: 'Immediately after rotation is enabled, then every 30 days thereafter' }, { id: 'C', text: 'At midnight UTC on the 30th day after creation' }, { id: 'D', text: '30 days after the last manual secret value update' }], correct: ['B'], explanation: 'When you enable rotation with a schedule, Secrets Manager triggers the rotation Lambda immediately for the first rotation, then follows the configured schedule.', distractors: { A: 'The first rotation does not wait 30 days — it fires immediately upon enabling rotation.', C: 'Rotation does not use midnight UTC as a trigger — it fires immediately when rotation is first configured.', D: 'The schedule starts from when rotation is enabled — not from the last manual update.' } },
  { id: 'd1-sec-003', domain: 1, topics: ['Secrets Manager', 'cross-account'], type: 'single', stem: 'A Lambda in Account A needs a secret stored in Account B Secrets Manager. What must be configured?', options: [{ id: 'A', text: 'Replicate the secret to Account A' }, { id: 'B', text: 'Resource policy on the secret allows Account A principal; KMS key policy also allows Account A' }, { id: 'C', text: 'Enable Secrets Manager replication to sync the secret to Account A automatically' }, { id: 'D', text: 'Share the secret via AWS RAM' }], correct: ['B'], explanation: 'Cross-account secret access: resource policy on the secret allows the Account A role. If the secret uses a CMK, the KMS key policy must also allow Account A to use the key.', distractors: { A: 'Cross-account Secrets Manager access is fully supported via resource-based policies — no copy needed.', C: 'Replication creates copies in other regions within the same account — not for cross-account access.', D: 'AWS RAM does not support Secrets Manager secrets — resource policies are the correct mechanism.' } },
  { id: 'd1-sec-004', domain: 1, topics: ['Secrets Manager', 'SSM Parameter Store'], type: 'single', stem: 'An application needs 500 secrets with automatic rotation and costs must be minimized. What is the tradeoff between Secrets Manager and Parameter Store?', options: [{ id: 'A', text: 'Parameter Store SecureString: no per-secret charge but no automatic rotation; Secrets Manager: $0.40/secret/month with built-in rotation' }, { id: 'B', text: 'Parameter Store: $0.40/secret/month with built-in rotation; Secrets Manager: free with manual rotation only' }, { id: 'C', text: 'Both cost the same at scale' }, { id: 'D', text: 'Parameter Store supports auto-rotation via EventBridge; Secrets Manager manages rotation natively via Lambda' }], correct: ['A'], explanation: 'SSM Parameter Store SecureString: no per-secret charge (standard tier) but no built-in rotation. Secrets Manager: $0.40/secret/month with built-in Lambda-based rotation. 500 secrets = $200/month with auto-rotation.', distractors: { B: 'Costs are inverted — Parameter Store standard tier is free; Secrets Manager has the per-secret monthly charge.', C: 'Secrets Manager has no free tier for large volumes — each secret is billed at $0.40/month.', D: 'Parameter Store requires custom automation for rotation — there is no native rotation feature at all.' } },
  { id: 'd1-sec-005', domain: 1, topics: ['Secrets Manager', 'versioning'], type: 'single', stem: 'What staging labels does Secrets Manager use during rotation?', options: [{ id: 'A', text: 'ACTIVE, PENDING, and PREVIOUS track the three version states during rotation' }, { id: 'B', text: 'AWSCURRENT (active), AWSPENDING (new value during rotation), AWSPREVIOUS (prior version after rotation)' }, { id: 'C', text: 'VERSION_1, VERSION_2, etc.' }, { id: 'D', text: 'Only AWSCURRENT and AWSPREVIOUS' }], correct: ['B'], explanation: 'Secrets Manager uses three staging labels: AWSCURRENT (active), AWSPENDING (new value being tested during rotation), AWSPREVIOUS (prior value kept for rollback). The Lambda moves labels at each step.', distractors: { A: 'ACTIVE, PENDING, PREVIOUS are not the actual label names — Secrets Manager uses AWS-prefixed labels.', C: 'Labels are not numeric versions — they are named AWSCURRENT, AWSPENDING, and AWSPREVIOUS.', D: 'AWSPENDING is a real label used throughout rotation — all three labels exist and are used.' } },
  { id: 'd1-sec-006', domain: 1, topics: ['CloudTrail', 'default events'], type: 'single', stem: 'A CloudTrail trail is created. Which events are logged by default?', options: [{ id: 'A', text: 'All events including S3 object-level reads and writes by default' }, { id: 'B', text: 'Management events (control plane API calls) by default; data events must be explicitly enabled' }, { id: 'C', text: 'Only IAM and billing events' }, { id: 'D', text: 'All read events only; write events must be opted into per service' }], correct: ['B'], explanation: 'CloudTrail logs management events (CreateBucket, RunInstances, etc.) by default. Data events (S3 GetObject, Lambda invocations) are not logged by default and must be explicitly enabled.', distractors: { A: 'S3 object-level events are data events — they are not enabled by default, even with a trail active.', C: 'CloudTrail logs management events for all supported services by default — not IAM only.', D: 'CloudTrail does not split management events into read-only default — all management events are included.' } },
  { id: 'd1-sec-007', domain: 1, topics: ['CloudTrail', 'integrity'], type: 'single', stem: 'How do you verify CloudTrail log files have not been tampered with after delivery to S3?', options: [{ id: 'A', text: 'Enable S3 versioning' }, { id: 'B', text: 'Enable log file integrity validation' }, { id: 'C', text: 'Enable S3 Object Lock on the log bucket to prevent any modification to log files' }, { id: 'D', text: 'Compare log file modification timestamps against the original delivery timestamp' }], correct: ['B'], explanation: 'CloudTrail log file integrity validation creates hourly digest files containing SHA-256 hashes of each log file, signed using AWS private key. The aws cloudtrail validate-logs command verifies the signatures.', distractors: { A: 'S3 versioning shows changes but does not prove which version is authentic or detect unauthorized modifications.', C: 'Object Lock prevents future changes but does not validate integrity of already-written files.', D: 'File modification timestamps can be forged — cryptographic hash signatures are the reliable validation method.' } },
  { id: 'd1-sec-008', domain: 1, topics: ['CloudTrail', 'Organizations'], type: 'single', stem: 'A company has 50 AWS accounts in an Organization. How to centralize CloudTrail logs with minimum effort?', options: [{ id: 'A', text: 'Create a trail in each account and configure S3 cross-account replication to a central bucket' }, { id: 'B', text: 'Create an organization trail in the management account' }, { id: 'C', text: 'Enable AWS Config in all accounts and use Config Aggregator to centralize trail output' }, { id: 'D', text: 'Use Control Tower to enable CloudTrail' }], correct: ['B'], explanation: 'Organization trails: created once in the management account, apply to all current and future member accounts, log to a central S3 bucket. Eliminates per-account trail setup entirely.', distractors: { A: 'Per-account trails plus replication work but add operational overhead — organization trails achieve this natively.', C: 'AWS Config tracks resource configuration changes — it does not consolidate CloudTrail event logs.', D: 'Control Tower sets up organization trails but the underlying mechanism is an organization trail you can create directly.' } },
  { id: 'd1-sec-009', domain: 1, topics: ['CloudTrail', 'CloudWatch', 'alerting'], type: 'single', stem: 'Alert within 5 minutes when the AWS root account logs in to the console. How?', options: [{ id: 'A', text: 'CloudTrail → CloudWatch Logs → metric filter for root ConsoleLogin events → CloudWatch Alarm → SNS' }, { id: 'B', text: 'Enable GuardDuty' }, { id: 'C', text: 'S3 event notification on the CloudTrail bucket triggers Lambda on each new log file delivery' }, { id: 'D', text: 'AWS Config rule evaluates root login events and triggers an SNS alert on violation' }], correct: ['A'], explanation: 'Standard pattern: CloudTrail → CloudWatch Logs → metric filter on ConsoleLogin with userIdentity.type=Root → CloudWatch Alarm → SNS notification. Near-real-time alerting within minutes.', distractors: { B: 'GuardDuty detects suspicious root usage patterns but is not configured as a guaranteed sub-5-minute alert.', C: 'Lambda on S3 events adds more latency — CloudWatch Logs metric filters provide near-real-time detection.', D: 'AWS Config rules evaluate resource configuration state — root console login is an event, not a configuration change.' } },
  { id: 'd1-sec-010', domain: 1, topics: ['CloudTrail', 'data events', 'S3'], type: 'single', stem: 'An S3 bucket stores sensitive data. All read and write object access must be audited. What must be enabled?', options: [{ id: 'A', text: 'S3 server access logging' }, { id: 'B', text: 'CloudTrail data events for S3 with Read and Write selectors on the specific bucket ARN' }, { id: 'C', text: 'S3 event notifications to SQS' }, { id: 'D', text: 'VPC Flow Logs' }], correct: ['B'], explanation: 'CloudTrail S3 data events with Read+Write selectors capture GetObject, PutObject, DeleteObject, etc. with principal identity, source IP, and timestamp — the authoritative audit trail for S3 access.', distractors: { A: 'S3 server access logging works but lacks IAM principal identity context — CloudTrail provides full identity information.', C: 'S3 event notifications trigger workflows — they are not an audit log and miss read events like GetObject.', D: 'VPC Flow Logs capture network IP and port metadata — not S3 object-level access with identity context.' } },
  { id: 'd1-sec-011', domain: 1, topics: ['CloudTrail', 'global services'], type: 'single', stem: 'A single-region trail is in us-east-1. An attacker creates an IAM user from eu-west-1. Is this logged?', options: [{ id: 'A', text: 'No' }, { id: 'B', text: 'Yes' }, { id: 'C', text: 'No' }, { id: 'D', text: 'Yes' }], correct: ['B'], explanation: 'IAM is a global service. CloudTrail logs global service events (IAM, STS, CloudFront) in the trail\'s home region even for single-region trails. Enable "Include global service events" in the trail settings.', distractors: { A: 'Global service events are an exception — IAM events route to the configured trail regardless of API call origin.', C: 'No separate global trail is needed — the "Include global service events" setting handles this on any trail.', D: 'Global service events are logged once in the home region — not duplicated across all regional trails.' } },
  { id: 'd1-sec-012', domain: 1, topics: ['Secrets Manager', 'KMS', 'default encryption'], type: 'single', stem: 'Secrets Manager encrypts secret values. What key does it use by default?', options: [{ id: 'A', text: 'An S3-managed key (SSE-S3)' }, { id: 'B', text: 'The AWS managed key for Secrets Manager (aws/secretsmanager) at no additional storage cost' }, { id: 'C', text: 'A customer master key that you must create and specify during secret creation' }, { id: 'D', text: 'No encryption by default' }], correct: ['B'], explanation: 'Secrets Manager always encrypts secrets. Default is the AWS managed key aws/secretsmanager (no cost beyond KMS API calls). You can specify a CMK for additional control and key rotation management.', distractors: { A: 'SSE-S3 is for S3 objects — Secrets Manager uses KMS-based encryption, not an S3-managed key.', C: 'CMK is optional — the aws/secretsmanager managed key is used by default without any CMK creation.', D: 'Secrets Manager encrypts all secrets by default — there is no way to store an unencrypted secret.' } },
  { id: 'd1-sec-013', domain: 1, topics: ['SSM Parameter Store', 'SecureString'], type: 'single', stem: 'A Lambda function needs a database password at runtime. Should it use Parameter Store String or SecureString?', options: [{ id: 'A', text: 'String: stored as plaintext in Parameter Store; SecureString: KMS-encrypted at rest' }, { id: 'B', text: 'String: encrypted automatically by Parameter Store; SecureString: double-encrypted' }, { id: 'C', text: 'Both are equally secure' }, { id: 'D', text: 'SecureString requires extra IAM permissions; String does not' }], correct: ['A'], explanation: 'Parameter Store String values are stored in plaintext. SecureString values are encrypted with KMS at rest. Always use SecureString for passwords, API keys, and any sensitive credentials.', distractors: { B: 'String parameters are not encrypted — they are stored as plaintext. There is no automatic encryption.', C: 'The security difference is significant — String is plaintext, SecureString uses KMS encryption at rest.', D: 'Both types require IAM permissions — the fundamental difference is encryption at rest, not the permission model.' } },
  { id: 'd1-sec-014', domain: 1, topics: ['CloudTrail', 'Lake'], type: 'single', stem: 'A security team needs to query 12 months of CloudTrail logs for all API calls by a specific IAM role. Most efficient approach?', options: [{ id: 'A', text: 'Download all CloudTrail JSON files from S3 and grep for the role name locally' }, { id: 'B', text: 'CloudTrail Lake' }, { id: 'C', text: 'Use the CloudTrail console' }, { id: 'D', text: 'Stream CloudTrail to CloudWatch Logs and use Insights query to filter by role ARN' }], correct: ['B'], explanation: 'CloudTrail Lake: managed event data store for CloudTrail events, queryable with SQL. Efficient large-scale forensic queries without managing S3 + Athena table setup or parsing JSON files.', distractors: { A: 'Scripted grep over 12 months of JSON files is slow and complex — CloudTrail Lake is purpose-built for this use case.', C: 'CloudTrail console shows 90-day history only — not 12 months, and filtering by principal is limited.', D: 'CloudWatch Logs Insights works but has retention limits and requires manual setup — CloudTrail Lake handles long-term querying natively.' } },
  { id: 'd1-sec-015', domain: 1, topics: ['Secrets Manager', 'Lambda caching'], type: 'single', stem: 'Best practice for retrieving a Secrets Manager secret in a high-volume Lambda function?', options: [{ id: 'A', text: 'Retrieve the secret on every Lambda invocation to ensure the latest rotated value is used' }, { id: 'B', text: 'Cache the secret in Lambda initialization code outside the handler; re-fetch only when AuthenticationFailedException occurs' }, { id: 'C', text: 'Store the secret value in Lambda environment variables at deployment time' }, { id: 'D', text: 'Hard-code the secret ARN in the handler and retrieve using GetSecretValue each time' }], correct: ['B'], explanation: 'Best practice: retrieve during Lambda init (cold start), cache in memory. On rotation, AuthenticationFailedException triggers a re-fetch from Secrets Manager. Balances freshness with API call efficiency.', distractors: { A: 'Retrieving on every invocation makes unnecessary API calls and adds latency to every function call at scale.', C: 'Environment variables at deploy time bake in the secret — defeats automatic rotation entirely.', D: 'GetSecretValue on every invocation is functionally correct but creates unnecessary API calls for high-volume functions.' } },
  { id: 'd1-sec-016', domain: 1, topics: ['CloudTrail', 'S3 bucket policy'], type: 'single', stem: 'CloudTrail log files in S3 should only be writable by CloudTrail, not by any IAM user. What enforces this?', options: [{ id: 'A', text: 'Enable MFA Delete on the S3 bucket to require MFA for all write and delete operations' }, { id: 'B', text: 'S3 bucket policy with explicit Deny PutObject for all principals except the CloudTrail service' }, { id: 'C', text: 'S3 Block Public Access prevents unauthorized IAM users from writing to the bucket' }, { id: 'D', text: 'S3 Object Lock in governance mode prevents unauthorized writes to existing log files' }], correct: ['B'], explanation: 'S3 bucket policy with Deny for PutObject/DeleteObject to all principals except aws:PrincipalService=cloudtrail.amazonaws.com ensures only CloudTrail writes logs — even admins cannot overwrite or delete.', distractors: { A: 'MFA Delete requires MFA for version deletion but does not prevent PutObject by IAM admins.', C: 'Block Public Access prevents public anonymous access — it does not restrict IAM user writes to the bucket.', D: 'Object Lock prevents modifications after writing but does not block authorized IAM admins from writing new objects.' } },
  { id: 'd1-sec-017', domain: 1, topics: ['SSM Parameter Store', 'hierarchy', 'IAM'], type: 'single', stem: 'Parameter Store parameters are at /prod/myapp/db/password. What is the key benefit of this hierarchy?', options: [{ id: 'A', text: 'Parameters in the same hierarchy automatically share the same KMS encryption key' }, { id: 'B', text: 'IAM policies use path-based wildcard resources to grant access to an entire subtree (e.g., /prod/myapp/*)' }, { id: 'C', text: 'Hierarchical parameters replicate across regions automatically for high availability' }, { id: 'D', text: 'Parameters in the same hierarchy are returned in one API call without any additional configuration' }], correct: ['B'], explanation: 'Hierarchical naming enables IAM policy resource ARNs with wildcards: arn:aws:ssm:*:*:parameter/prod/myapp/* grants access to all parameters under that path — clean IAM control at the application level.', distractors: { A: 'Parameters do not automatically share KMS keys based on path — encryption keys are configured per parameter.', C: 'Parameter Store does not auto-replicate across regions based on path hierarchy.', D: 'GetParametersByPath retrieves multiple parameters by path — it must be called explicitly, not automatic.' } },
  { id: 'd1-sec-018', domain: 1, topics: ['Secrets Manager', 'replication'], type: 'single', stem: 'A Secrets Manager secret in us-east-1 needs availability in eu-west-1 for disaster recovery. Solution?', options: [{ id: 'A', text: 'Secrets Manager does not support cross-region access' }, { id: 'B', text: 'Enable cross-region replication on the secret' }, { id: 'C', text: 'Use S3 cross-region replication on the Secrets Manager backing store bucket' }, { id: 'D', text: 'Create a Lambda that copies the secret value to eu-west-1 on each rotation event' }], correct: ['B'], explanation: 'Secrets Manager supports multi-region replication. The replica is read-only and synced from the primary. Applications in eu-west-1 read from the local replica for lower latency and regional DR.', distractors: { A: 'Cross-region replication is a built-in feature — separate independent secrets with manual sync are not required.', C: 'Secrets Manager does not expose an S3 backing store to users — replication is a service-level feature.', D: 'Custom Lambda replication adds operational complexity — the built-in replication feature is the correct approach.' } },
  { id: 'd1-sec-019', domain: 1, topics: ['CloudTrail', 'Insights'], type: 'single', stem: 'CloudTrail Insights is enabled on a trail. What does it detect?', options: [{ id: 'A', text: 'Unusual network traffic patterns that may indicate a DDoS attack' }, { id: 'B', text: 'Unusual API call volumes or error rates that deviate from established baseline activity' }, { id: 'C', text: 'Unauthorized IAM policy changes that violate least-privilege principles' }, { id: 'D', text: 'Compliance violations such as public S3 buckets or overly permissive security groups' }], correct: ['B'], explanation: 'CloudTrail Insights establishes a baseline of normal API call rates and error rates. It detects unusual spikes — e.g., sudden burst of TerminateInstances or unusually high API error rates — and generates Insight events.', distractors: { A: 'DDoS detection is AWS Shield\'s domain — CloudTrail Insights tracks API call volume patterns, not network traffic.', C: 'IAM Access Analyzer or AWS Config rules detect policy issues — Insights detects volume and rate anomalies.', D: 'AWS Config rules and Security Hub check compliance posture — Insights detects behavioral anomalies in API usage.' } },
  { id: 'd1-sec-020', domain: 1, topics: ['SSM Parameter Store', 'Lambda extension'], type: 'single', stem: 'A Lambda reads a Parameter Store SecureString on every invocation. How to reduce API calls and latency?', options: [{ id: 'A', text: 'Enable Lambda Provisioned Concurrency' }, { id: 'B', text: 'Use the AWS Parameters and Secrets Lambda Extension' }, { id: 'C', text: 'Store the parameter value in a DynamoDB table and query from Lambda on each invocation' }, { id: 'D', text: 'Migrate to Lambda environment variables' }], correct: ['B'], explanation: 'AWS Parameters and Secrets Lambda Extension: a layer that caches Parameter Store and Secrets Manager values at a local HTTP endpoint within the Lambda. TTL controls staleness. Zero changes to Lambda function code.', distractors: { A: 'Provisioned Concurrency keeps instances warm but does not cache parameter values — cold code still calls SSM.', C: 'DynamoDB caching adds infrastructure and custom sync logic — the Lambda extension handles this natively.', D: 'Environment variables bake in values at deploy time — rotation and updates require redeployment to take effect.' } },
  { id: 'd1-sec-021', domain: 1, topics: ['Secrets Manager', 'IAM', 'least privilege'], type: 'single', stem: 'A Lambda should only read one specific secret, not list or describe any others. Minimum required IAM policy?', options: [{ id: 'A', text: 'Allow secretsmanager:* on the specific secret ARN only' }, { id: 'B', text: 'Allow secretsmanager:GetSecretValue on the specific secret ARN only' }, { id: 'C', text: 'Allow secretsmanager:GetSecretValue and secretsmanager:ListSecrets on all resources' }, { id: 'D', text: 'Allow secretsmanager:GetSecretValue on arn:aws:secretsmanager:*:*:secret:* for all secrets' }], correct: ['B'], explanation: 'Least privilege: only GetSecretValue is needed to read a secret. Scope the resource to the exact secret ARN. No List, Describe, or wildcard permissions are required.', distractors: { A: 'secretsmanager:* includes CreateSecret, DeleteSecret, and RotateSecret — far more than reading a secret value.', C: 'ListSecrets is not required for reading a specific secret — and the resource must be scoped to one ARN.', D: 'Wildcard resource grants access to all secrets in the account — this violates least-privilege principles.' } },
  { id: 'd1-sec-022', domain: 1, topics: ['CloudTrail', 'data events cost'], type: 'single', stem: 'CloudTrail S3 data events are enabled account-wide. A bucket has millions of GetObject calls daily. Cost concern?', options: [{ id: 'A', text: 'S3 data events are included in the standard CloudTrail management event pricing' }, { id: 'B', text: 'Data events cost $0.10 per 100,000 events' }, { id: 'C', text: 'S3 data events are free when stored in S3; charges apply only for CloudTrail Lake' }, { id: 'D', text: 'The first 1 million data events per month are free; charges apply only beyond that' }], correct: ['B'], explanation: 'CloudTrail data events cost $0.10 per 100,000 events recorded. Millions of daily S3 API calls can generate hundreds of dollars per month. Use specific bucket ARN selectors to limit scope and cost.', distractors: { A: 'Data events are billed separately from management events — they are not included in base CloudTrail pricing.', C: 'Data events are charged when recorded to any destination — S3 delivery and CloudTrail Lake both incur charges.', D: 'CloudTrail has no free tier for data events beyond management event coverage on the first trail.' } },
  { id: 'd1-sec-023', domain: 1, topics: ['CloudTrail', 'SNS notification'], type: 'single', stem: 'How do you notify a security team when new CloudTrail log files are delivered to S3?', options: [{ id: 'A', text: 'Configure CloudTrail to publish SNS notifications for each log file delivered to S3' }, { id: 'B', text: 'Set up S3 event notification on the CloudTrail bucket for ObjectCreated events forwarding to SQS' }, { id: 'C', text: 'Create an EventBridge rule triggered by CloudTrail log delivery events in real-time' }, { id: 'D', text: 'Configure a CloudWatch Logs subscription filter that alerts on each log file delivery' }], correct: ['A'], explanation: 'CloudTrail can be configured with an SNS topic — it publishes a notification for each log file delivered to S3. The notification includes the S3 object location for downstream processing.', distractors: { B: 'S3 event notifications work but bypass CloudTrail\'s built-in SNS integration — option A is simpler and native.', C: 'EventBridge does not have a direct event source for CloudTrail S3 log file deliveries — CloudTrail SNS is the native mechanism.', D: 'CloudWatch Logs subscription filters monitor log data — not S3 file delivery events.' } },
  { id: 'd1-sec-024', domain: 1, topics: ['Secrets Manager', 'supported databases'], type: 'single', stem: 'Secrets Manager has built-in automatic rotation support for which databases?', options: [{ id: 'A', text: 'Only Amazon RDS MySQL' }, { id: 'B', text: 'Amazon RDS (all engines), Amazon Aurora, Amazon Redshift, and Amazon DocumentDB' }, { id: 'C', text: 'Any database reachable from a rotation Lambda in the same VPC subnet' }, { id: 'D', text: 'Only Aurora Serverless' }], correct: ['B'], explanation: 'Secrets Manager provides AWS-managed rotation Lambda templates for: all RDS engines (MySQL, PostgreSQL, Oracle, SQL Server, MariaDB), Aurora, Redshift, and DocumentDB. Other databases need custom Lambda.', distractors: { A: 'AWS provides templates for all RDS engines plus Aurora, Redshift, and DocumentDB — not MySQL only.', C: 'VPC reachability is a deployment requirement — not a definition of which databases have managed rotation support.', D: 'Provisioned RDS is fully supported with managed rotation — Aurora Serverless is just one of many supported engines.' } },
  { id: 'd1-sec-025', domain: 1, topics: ['CloudTrail', 'compliance audit'], type: 'single', stem: 'Auditors need evidence that all AWS API calls in the account are logged without gaps. What demonstrates this?', options: [{ id: 'A', text: 'Show that CloudTrail is enabled in all regions and provide the raw S3 log files' }, { id: 'B', text: 'Multi-region trail with log file integrity validation enabled; show validated digest files proving completeness' }, { id: 'C', text: 'Provide CloudWatch Logs from all regions showing CloudTrail delivery confirmation events' }, { id: 'D', text: 'Enable Config and show that the cloud-trail-enabled rule reports no violations' }], correct: ['B'], explanation: 'Multi-region trail ensures all regions are covered. Log file integrity validation digest files, signed by AWS, prove no log files were deleted or modified. Together they satisfy completeness and non-repudiation.', distractors: { A: 'Showing raw logs demonstrates coverage but not integrity — auditors need tamper-evidence proof.', C: 'CloudWatch delivery events show files arrived — not that they are complete and unmodified.', D: 'Config rule checks if CloudTrail is enabled — not whether logs are complete and cryptographically verified.' } },
  { id: 'd1-sec-026', domain: 1, topics: ['SSM Parameter Store', 'advanced tier'], type: 'single', stem: 'Parameter Store advanced tier is needed for parameters larger than 4KB. What else does advanced tier provide?', options: [{ id: 'A', text: 'Advanced tier adds built-in automatic rotation capability to Parameter Store' }, { id: 'B', text: 'Advanced tier supports up to 8KB values, parameter policies (TTL, no-change notification), and higher throughput' }, { id: 'C', text: 'Advanced tier adds automatic cross-region replication for all parameters' }, { id: 'D', text: 'Advanced tier adds native integration with Secrets Manager for automatic rotation' }], correct: ['B'], explanation: 'Advanced tier: up to 8KB per parameter, parameter policies (expiration TTL, no-change notification, required access notification), and higher API throughput. Standard tier: 4KB max, no policies.', distractors: { A: 'Rotation is not a Parameter Store feature in any tier — use Secrets Manager for automatic credential rotation.', C: 'Parameter Store does not support cross-region replication in standard or advanced tier.', D: 'Advanced tier has no Secrets Manager integration — they are separate, independent services.' } },
  { id: 'd1-sec-027', domain: 1, topics: ['CloudTrail', 'event history retention'], type: 'single', stem: 'How long does CloudTrail Event History retain events in the console without creating a trail?', options: [{ id: 'A', text: '7 days' }, { id: 'B', text: '90 days' }, { id: 'C', text: '30 days' }, { id: 'D', text: '365 days' }], correct: ['B'], explanation: 'CloudTrail Event History in the console retains 90 days of management events automatically at no additional cost. For longer retention, create a trail to deliver logs to S3.', distractors: { A: '7 days is not CloudTrail\'s retention period — CloudWatch Logs uses 7-day as one retention tier option.', C: '30 days is not accurate — CloudTrail Event History retains 90 days of events automatically.', D: '365 days is not the automatic retention — a trail with S3 lifecycle policies achieves long-term storage.' } },
  { id: 'd1-sec-028', domain: 1, topics: ['Secrets Manager', 'pricing API calls'], type: 'single', stem: 'A secret in Secrets Manager is accessed 10,000 times per month. What determines the total cost?', options: [{ id: 'A', text: 'The $0.40/secret/month charge covers unlimited API calls' }, { id: 'B', text: 'Secrets Manager API calls: $0.05 per 10,000 calls, plus the per-secret monthly storage charge' }, { id: 'C', text: 'KMS API charges for each GetSecretValue decryption call, plus the secret storage charge' }, { id: 'D', text: 'Both Secrets Manager API call fees ($0.05/10K) and KMS decrypt charges per call apply' }], correct: ['D'], explanation: 'Secrets Manager pricing: $0.40/secret/month storage + $0.05 per 10,000 API calls + KMS API charges per decryption (unless using aws/secretsmanager managed key which has no per-call charge for Secrets Manager).', distractors: { A: 'The $0.40 is the storage charge only — API calls are billed separately at $0.05 per 10,000.', B: 'Secrets Manager API fees apply but KMS decrypt charges also apply for each GetSecretValue when using a CMK.', C: 'KMS charges apply but Secrets Manager API call charges are also separate — both pricing dimensions apply.' } },
  { id: 'd1-sec-029', domain: 1, topics: ['CloudTrail', 'EventBridge', 'remediation'], type: 'single', stem: 'How do you trigger automated remediation when an IAM policy is changed?', options: [{ id: 'A', text: 'CloudTrail cannot trigger automated actions' }, { id: 'B', text: 'EventBridge rule matching CloudTrail PutUserPolicy or AttachRolePolicy events triggers Lambda remediation' }, { id: 'C', text: 'Create a CloudWatch alarm on the IAM service namespace for policy change CloudWatch metrics' }, { id: 'D', text: 'AWS Config Auto Remediation evaluates the change and triggers SSM Automation documents' }], correct: ['B'], explanation: 'EventBridge receives CloudTrail management events in near-real-time. A rule matching PutUserPolicy or AttachRolePolicy can trigger a Lambda function for automated remediation or notification.', distractors: { A: 'CloudTrail events are published to EventBridge in near-real-time — automated triggers are fully supported.', C: 'IAM does not publish CloudWatch metrics for policy changes — EventBridge with CloudTrail is the correct pattern.', D: 'Config Auto Remediation works for configuration state violations — EventBridge+CloudTrail is faster for specific API events.' } },
  { id: 'd1-sec-030', domain: 1, topics: ['Secrets Manager', 'VPC endpoint'], type: 'single', stem: 'A Lambda in a private VPC needs Secrets Manager access. No internet gateway is available. Solution?', options: [{ id: 'A', text: 'Add a NAT Gateway to route Lambda traffic to Secrets Manager over the internet' }, { id: 'B', text: 'Create an Interface VPC Endpoint for Secrets Manager' }, { id: 'C', text: 'Use Parameter Store instead' }, { id: 'D', text: 'Enable VPC DNS hostname resolution' }], correct: ['B'], explanation: 'Interface VPC Endpoint for Secrets Manager creates a private DNS entry. Lambda calls secretsmanager.region.amazonaws.com and traffic routes through the endpoint ENI — no NAT or internet access needed.', distractors: { A: 'NAT Gateway adds internet routing — an Interface Endpoint keeps all traffic private within the AWS network.', C: 'Parameter Store also requires a VPC endpoint for private access — it has the same requirement.', D: 'DNS hostname resolution alone does not create a private route — the Interface Endpoint ENI is needed for private routing.' } },
  { id: 'd1-sec-031', domain: 1, topics: ['SSM Session Manager', 'audit logging'], type: 'single', stem: 'Session Manager is used for EC2 access instead of SSH. How are sessions audited?', options: [{ id: 'A', text: 'Session Manager sessions cannot be logged' }, { id: 'B', text: 'Configure session logging to S3 or CloudWatch Logs to capture full session transcript with commands and output' }, { id: 'C', text: 'CloudTrail logs the StartSession API call but does not capture session content itself' }, { id: 'D', text: 'Sessions are automatically logged to CloudWatch Logs without any additional configuration' }], correct: ['B'], explanation: 'Session Manager logs full session output (commands + responses) to S3 or CloudWatch Logs when configured. CloudTrail also records StartSession and TerminateSession API calls. Together they provide complete audit trails.', distractors: { A: 'Session Manager fully supports session logging — it is a primary advantage over SSH for audit purposes.', C: 'CloudTrail API call recording is not enough alone — session logging captures the full interactive transcript.', D: 'Session logging requires explicit configuration — it is not automatically enabled by default.' } },
  { id: 'd1-sec-032', domain: 1, topics: ['Secrets Manager', 'resource policy', 'org'], type: 'single', stem: 'A secret should be accessible only within the organization — blocked from any external account. What enforces this?', options: [{ id: 'A', text: 'Set the secret visibility to private mode in Secrets Manager account settings' }, { id: 'B', text: 'Attach a resource policy with Deny where aws:PrincipalOrgID does not match the organization ID' }, { id: 'C', text: 'Use a KMS key policy that denies decryption to any principal outside the organization' }, { id: 'D', text: 'Enable Secrets Manager org-level access control in the management account settings' }], correct: ['B'], explanation: 'Resource policy with Deny where aws:PrincipalOrgID != your org ID blocks all access from principals outside your organization — even if someone has a valid cross-account trust relationship.', distractors: { A: 'There is no "private mode" in Secrets Manager — access control is handled via IAM and resource policies.', C: 'KMS key policy is a useful additional control but does not prevent access to the secret value at the policy level.', D: 'No org-level access control setting exists in Secrets Manager — use resource policies with PrincipalOrgID condition.' } },
  { id: 'd1-sec-033', domain: 1, topics: ['CloudTrail', 'KMS encryption'], type: 'single', stem: 'CloudTrail logs in S3 must be encrypted with a customer CMK, not the default S3-managed key. How?', options: [{ id: 'A', text: 'Enable S3 default bucket encryption with the CMK' }, { id: 'B', text: 'Configure CloudTrail with a KMS key ARN' }, { id: 'C', text: 'Enable AWS Macie on the S3 bucket' }, { id: 'D', text: 'Set an S3 bucket ACL requiring KMS encryption from all principals writing to the bucket' }], correct: ['B'], explanation: 'CloudTrail has a built-in KMS encryption setting — specify the CMK ARN when creating or updating the trail. CloudTrail encrypts each log file with SSE-KMS before writing to S3.', distractors: { A: 'Bucket default encryption applies to objects without explicit encryption settings — CloudTrail specifies its own key, overriding bucket defaults.', C: 'Macie is a data classification service — it does not encrypt files.', D: 'S3 ACLs do not enforce encryption at write time — the CloudTrail KMS configuration is the correct mechanism.' } },
  { id: 'd1-sec-034', domain: 1, topics: ['CloudTrail', 'write-only events'], type: 'single', stem: 'A trail is configured to log "Write-only" management events. Which events are captured?', options: [{ id: 'A', text: 'Only IAM write events' }, { id: 'B', text: 'All mutating control-plane API calls' }, { id: 'C', text: 'All read events only' }, { id: 'D', text: 'All network-level write operations' }], correct: ['B'], explanation: 'Write-only management events include all mutating API calls across services (CreateBucket, RunInstances, DeleteTable). Read-only calls (Describe, List, Get) are excluded. Reduces log volume while capturing all changes.', distractors: { A: 'Write-only captures all mutating calls across all services — not limited to IAM events only.', C: 'Read events (Describe, List, Get) are captured by "Read-only" management events — the opposite selection.', D: 'Write management events are control plane (configuration changes) — not data plane writes like S3 PutObject.' } },
  { id: 'd1-sec-035', domain: 1, topics: ['Secrets Manager', 'rotation Lambda steps'], type: 'single', stem: 'What are the four steps a Secrets Manager rotation Lambda must implement?', options: [{ id: 'A', text: 'GenerateSecret, ValidateSecret, StoreSecret, UpdateSecret' }, { id: 'B', text: 'initRotation, generateValue, setDatabasePassword, completeRotation' }, { id: 'C', text: 'createSecret (generate), setSecret (update service), testSecret (verify), finishSecret (update AWSCURRENT)' }, { id: 'D', text: 'provisionSecret, activateSecret, testSecret, archiveSecret' }], correct: ['C'], explanation: 'Secrets Manager calls the rotation Lambda four times: createSecret (generate/store AWSPENDING), setSecret (update the actual service), testSecret (verify new credentials work), finishSecret (move AWSPENDING to AWSCURRENT).', distractors: { A: 'GenerateSecret etc. are not the actual step names — AWS uses createSecret, setSecret, testSecret, finishSecret.', B: 'initRotation, generateValue etc. are not the actual step names used by Secrets Manager rotation protocol.', D: 'provisionSecret, activateSecret etc. are not the actual Secrets Manager rotation step names.' } },
  { id: 'd1-sec-036', domain: 1, topics: ['SSM Parameter Store', 'GetParametersByPath'], type: 'single', stem: 'A deployment script needs all parameters under /prod/myapp/. Most efficient API call?', options: [{ id: 'A', text: 'GetParameter called once for each individually known parameter path' }, { id: 'B', text: 'GetParametersByPath with Path=/prod/myapp/ and Recursive=true returns all in paginated call' }, { id: 'C', text: 'ListParameters filtered by path prefix, then GetParameter for each result' }, { id: 'D', text: 'DescribeParameters with a Name filter for the path prefix returns all values' }], correct: ['B'], explanation: 'GetParametersByPath retrieves all parameters under a path in a single paginated call. WithDecryption=true also decrypts SecureString values inline. Far more efficient than per-parameter calls.', distractors: { A: 'Per-parameter GetParameter calls require knowing all parameter names and make N separate API calls.', C: 'ListParameters returns metadata only — a second GetParameter call is still needed for each parameter value.', D: 'DescribeParameters returns metadata only — no parameter values are returned by this API call.' } },
  { id: 'd1-sec-037', domain: 1, topics: ['CloudTrail', 'global events multi-region'], type: 'single', stem: 'A multi-region trail is created. Do IAM events appear in every region\'s log or only the home region?', options: [{ id: 'A', text: 'IAM events appear in every region\'s log file' }, { id: 'B', text: 'IAM global service events are logged once in the trail\'s home region' }, { id: 'C', text: 'IAM events always appear in us-east-1 only' }, { id: 'D', text: 'IAM events are not captured by CloudTrail' }], correct: ['B'], explanation: 'With multi-region trails, global service events (IAM, STS, CloudFront) are logged once in the home region — not duplicated to every region. The "Include global service events" option must be enabled.', distractors: { A: 'Global service events are not duplicated per region — they appear once in the trail\'s home region.', C: 'Home region is wherever the trail was created — it is not always or automatically us-east-1.', D: 'IAM events are fully captured by CloudTrail — IAM Access Analyzer is a separate policy analysis tool.' } },
  { id: 'd1-sec-038', domain: 1, topics: ['Secrets Manager', 'tagging', 'IAM'], type: 'single', stem: 'IAM policies need to restrict Secrets Manager access based on application name. Best mechanism?', options: [{ id: 'A', text: 'Use secret name prefixes in IAM resource ARNs: arn:aws:secretsmanager:*:*:secret:appname-*' }, { id: 'B', text: 'Tag secrets with Application=appname; IAM policy uses aws:ResourceTag/Application condition' }, { id: 'C', text: 'Both ARN prefix matching and tag-based conditions are valid and complementary approaches' }, { id: 'D', text: 'Create one Secrets Manager namespace per application and restrict IAM access per namespace' }], correct: ['C'], explanation: 'Two valid approaches: (1) Name-based ARN with wildcard like secret:myapp-*; (2) Tag-based with IAM condition aws:ResourceTag/Application=myapp. Both work; combining them provides defense in depth.', distractors: { A: 'ARN prefix matching is valid — but tag-based conditions are also valid and sometimes more flexible.', B: 'Tag-based conditions are valid — but ARN prefix matching is also valid and does not require tagging.', D: 'Secrets Manager does not have per-application namespaces — it is a flat regional service with named secrets.' } },
  { id: 'd1-sec-039', domain: 1, topics: ['GuardDuty', 'CloudTrail integration'], type: 'single', stem: 'GuardDuty is enabled. Does it require a separate CloudTrail trail configuration?', options: [{ id: 'A', text: 'Yes' }, { id: 'B', text: 'No' }, { id: 'C', text: 'Yes' }, { id: 'D', text: 'No' }], correct: ['B'], explanation: 'GuardDuty has native independent access to CloudTrail management events, VPC Flow Logs, and DNS logs — no S3 bucket or trail configuration needed. GuardDuty uses all three data sources for threat detection.', distractors: { A: 'GuardDuty does not read from an S3 bucket — it has a direct service-level access pipeline to CloudTrail events.', C: 'GuardDuty does not use CloudWatch Logs subscription filters — it has its own independent data access mechanism.', D: 'GuardDuty analyzes all three sources: CloudTrail events, VPC Flow Logs, and DNS query logs.' } },
  { id: 'd1-sec-040', domain: 1, topics: ['Secrets Manager', 'deletion protection'], type: 'single', stem: 'How does Secrets Manager protect against accidental deletion of a secret?', options: [{ id: 'A', text: 'Secrets Manager deletes immediately with no recovery window' }, { id: 'B', text: 'DeleteSecret schedules deletion with a minimum 7-day recovery window; RestoreSecret cancels it' }, { id: 'C', text: 'Secrets are protected by S3 Versioning on the backing store so deleted versions can be restored' }, { id: 'D', text: 'Only secrets with rotation enabled have a deletion protection window' }], correct: ['B'], explanation: 'DeleteSecret in Secrets Manager schedules the secret for deletion with a recovery window (7–30 days). During this window, RestoreSecret cancels the deletion. Immediate deletion requires --force-delete-without-recovery.', distractors: { A: 'Secrets are not immediately deleted — a recovery window (minimum 7 days) protects against accidental deletion.', C: 'Secrets Manager has no user-accessible S3 backing store — recovery is via the RestoreSecret API only.', D: 'All secrets have the recovery window regardless of rotation configuration.' } },
  { id: 'd1-sec-041', domain: 1, topics: ['CloudTrail', 'Lake forensics'], type: 'single', stem: 'An investigator needs all API calls made by a compromised IAM role over the last 6 months. Fastest solution?', options: [{ id: 'A', text: 'Download 6 months of CloudTrail JSON from S3 and parse with a custom script' }, { id: 'B', text: 'CloudTrail Lake SQL query on the event data store filtered by principal ARN and time range' }, { id: 'C', text: 'Search CloudTrail console Event History for the role name' }, { id: 'D', text: 'Review AWS Config timeline for the IAM role to see all associated API calls' }], correct: ['B'], explanation: 'CloudTrail Lake supports SQL queries over event data stores. Queries by principal ARN, event type, and time range return results in seconds — no S3 data parsing or Athena table setup required.', distractors: { A: 'Parsing raw JSON from S3 over 6 months takes hours and requires custom scripting — CloudTrail Lake returns results in seconds.', C: 'Event History only covers 90 days — the investigator needs 6 months of history.', D: 'AWS Config tracks resource configuration changes — not API call history by a specific role.' } },
  { id: 'd1-sec-042', domain: 1, topics: ['SSM Parameter Store', 'standard vs advanced'], type: 'single', stem: 'Which capability is ONLY available in Parameter Store Advanced tier, not Standard?', options: [{ id: 'A', text: 'SecureString parameters encrypted with KMS' }, { id: 'B', text: 'Parameter policies such as expiration TTL and no-change notification alerts' }, { id: 'C', text: 'Hierarchical parameter names with path-based IAM access control' }, { id: 'D', text: 'Cross-region read access for parameters stored in other regions' }], correct: ['B'], explanation: 'Parameter policies (expiration date, no-change notification, required access alerts) are Advanced tier only. SecureString, hierarchical names, and path-based IAM policies all work in Standard tier.', distractors: { A: 'SecureString with KMS encryption is fully available in Standard tier — no Advanced upgrade required.', C: 'Hierarchical names and path-based IAM policies are Standard tier features — no Advanced needed.', D: 'Parameter Store does not support cross-region replication or read access in any tier.' } },
  { id: 'd1-sec-043', domain: 1, topics: ['Secrets Manager', 'single vs alternating rotation'], type: 'single', stem: 'What is the difference between single-user and alternating-user rotation in Secrets Manager?', options: [{ id: 'A', text: 'Single-user rotates the password for one user; alternating-user creates a new IAM user on each rotation' }, { id: 'B', text: 'Single-user updates the password in place with a brief window; alternating-user uses two users for zero-downtime rotation' }, { id: 'C', text: 'Single-user rotates only once; alternating-user rotates on a recurring automatic schedule' }, { id: 'D', text: 'Single-user rotation is free; alternating-user incurs an additional charge per rotation cycle' }], correct: ['B'], explanation: 'Single-user rotation: updates the same user\'s password (brief window during rotation). Alternating-user: maintains two database users — while one is AWSCURRENT, the other is updated — zero downtime.', distractors: { A: 'Neither strategy creates new IAM users — they manage database credentials, not IAM user accounts.', C: 'Both strategies rotate on a recurring schedule — the difference is the mechanism, not the frequency.', D: 'Secrets Manager pricing is per secret per month — rotation events and strategies have no additional per-cycle charge.' } },
  { id: 'd1-sec-044', domain: 1, topics: ['CloudTrail', 'data vs management events'], type: 'single', stem: 'Which activity would NOT appear in CloudTrail management events?', options: [{ id: 'A', text: 'Creating an EC2 security group' }, { id: 'B', text: 'An S3 GetObject API call to download a file from a bucket' }, { id: 'C', text: 'Attaching an IAM policy to a role' }, { id: 'D', text: 'Launching an EC2 instance with RunInstances' }], correct: ['B'], explanation: 'S3 GetObject is a data event — not a management event. Management events are control-plane operations (Create, Modify, Delete). Data events require explicit enablement in trail configuration.', distractors: { A: 'CreateSecurityGroup is a management event — it modifies resource configuration at the control plane.', C: 'AttachRolePolicy is a management event — captured by default in all CloudTrail trails.', D: 'RunInstances is a management event — it is captured by default without any additional configuration.' } },
  { id: 'd1-sec-045', domain: 1, topics: ['Secrets Manager', 'EC2 IAM role'], type: 'single', stem: 'An application on EC2 needs Secrets Manager access without hard-coded credentials. Best approach?', options: [{ id: 'A', text: 'Store AWS credentials in a config file on the instance with restricted file permissions (chmod 600)' }, { id: 'B', text: 'Attach an IAM role to the EC2 instance with secretsmanager:GetSecretValue on the secret ARN' }, { id: 'C', text: 'Pass the secret ARN as a user data environment variable at EC2 launch time' }, { id: 'D', text: 'Connect via a Secrets Manager VPN that the application uses for credential retrieval' }], correct: ['B'], explanation: 'IAM role on EC2 provides temporary credentials via instance metadata — no hard-coded credentials. The role policy allows GetSecretValue on the specific secret. The Secrets Manager SDK uses the role automatically.', distractors: { A: 'File-based credentials are static, require manual rotation, and can leak — IAM roles provide temporary rotating credentials.', C: 'User data is visible in instance metadata — appropriate for passing config ARNs, not actual credentials.', D: 'There is no "Secrets Manager VPN" — applications call the Secrets Manager HTTPS API endpoint via the AWS SDK.' } },
]
